function P.learn()
local LRb,MRb={},{}
local NRb,ORb=0,0
for PRb,QRb in ipairs(P.mine)do
local RRb=QRb._stats
local SRb=RRb.id.Value
local TRb=RRb:FindFirstChild(Ekc[2704])and RRb.total_damage.Value or 0
if not M.isFarm(SRb)then
LRb[SRb]=(LRb[SRb]or 0)+TRb
MRb[SRb]=(MRb[SRb]or 0)+P.liveDps(QRb,SRb)/math.max(0.5,M.nudge(SRb))
local URb=M.passive(SRb).mark
if URb then
MRb[SRb]=MRb[SRb]+URb.dot*RRb.damage.Value
end
NRb=NRb+TRb
end
end
for VRb,WRb in pairs(MRb)do
ORb=ORb+WRb
end
if NRb<=0 or ORb<=0 then
return
end
P.lastEff={}
for XRb,YRb in pairs(LRb)do
local ZRb,_Rb=YRb/NRb,MRb[XRb]/ORb
if _Rb>0.02 then
local aSb=I.learn[XRb]or{eff=1,n=0}
local bSb=math.max(0.02,0.25*math.sqrt(30/(30+aSb.n)))
local cSb=L.clamp(ZRb/_Rb,0.3,3)
P.lastEff[XRb]=math.floor(cSb*1000+0.5)/1000
aSb.eff=aSb.eff+(cSb-aSb.eff)*bSb
aSb.n=aSb.n+1
I.learn[XRb]=aSb
end
end
end
